275	func parseTrailResumeRepoFlag(value string) (trailResumeRepository, error) {
276		value = strings.TrimSpace(value)
277		if value == "" {
278			return trailResumeRepository{}, nil
279		}
280		owner, repo, err := parseGitHubURL(value)
281		if err != nil {
282			return trailResumeRepository{}, err
283		}
284		return trailResumeRepository{Forge: "gh", Owner: owner, Repo: repo}, nil
285	}
286	
287	func validateTrailResumeExpectedRepo(current, expected trailResumeRepository) error {
288		if strings.TrimSpace(expected.Repo) == "" {
289			return nil
290		}
291		if current.Forge == expected.Forge &&
292			strings.EqualFold(current.Owner, expected.Owner) &&
293			strings.EqualFold(current.Repo, expected.Repo) {
294			return nil
295		}
296		return fmt.Errorf("this command targets repository %s/%s, but the current checkout is %s/%s", expected.Owner, expected.Repo, current.Owner, current.Repo)
297	}
298	
299	func validateTrailResumeExpectedBranch(found *api.TrailResource, expectedBranch string) error {
300		expectedBranch = strings.TrimSpace(expectedBranch)
301		if expectedBranch == "" {
302			return nil
303		}
304		actualBranch := strings.TrimSpace(found.Branch)
305		if actualBranch == expectedBranch {
306			return nil
307		}
308		return fmt.Errorf("%s is attached to branch %q, not expected branch %q", describeTrailRef(found), actualBranch, expectedBranch)
309	}
310	
311	func knownTrailResumeSessionsForContext(sessions []trailResumeSessionContext, skipped int, sessionErr error) ([]trailResumeSessionContext, int, string) {
312		if sessionErr != nil {
313			return nil, 0, sessionErr.Error()
314		}
315		return sessions, skipped, ""
316	}
317	
318	func resumeTrailLatest(ctx context.Context, cmd *cobra.Command, branch string, force bool, preferredSessionID string) error {
319		w := cmd.OutOrStdout()
320		errW := cmd.ErrOrStderr()
321	
322		if !ensureTrailResumeBranchAvailable(ctx, w, branch) {
323			return nil
324		}
325		proceed, err := switchToBranchForResume(ctx, w, errW, branch, trailResumeSkipBranchPrompts(force))
326		if err != nil || !proceed {
327			return err
328		}
329		sessions, err := restoreFromCurrentBranch(ctx, w, errW, branch, force)
330		if err != nil {
331			return err
332		}
333		return continueTrailRestoredSessions(ctx, cmd, sessions, preferredSessionID, force)
334	}
335	
336	func resumeTrailCheckpoint(ctx context.Context, cmd *cobra.Command, branch string, checkpointID id.CheckpointID, preferredSessionID string, force bool) error {
337		w := cmd.OutOrStdout()
338		errW := cmd.ErrOrStderr()
339	
340		if !ensureTrailResumeBranchAvailable(ctx, w, branch) {
341			return nil
342		}
343		proceed, err := switchToBranchForResume(ctx, w, errW, branch, trailResumeSkipBranchPrompts(force))
344		if err != nil || !proceed {
345			return err
346		}
347		sessions, err := restoreByCheckpointID(ctx, w, errW, checkpointID, force)
348		if err != nil {
349			return err
350		}
351		return continueTrailRestoredSessions(ctx, cmd, sessions, preferredSessionID, force)
352	}
353	
354	func trailResumeSkipBranchPrompts(force bool) bool {
355		return force || !interactive.CanPromptInteractively()
356	}
357	
358	func trailResumeCanPromptRestoredSessions(force bool) bool {
359		return !force && interactive.CanPromptInteractively()
360	}
361	
362	func continueTrailRestoredSessions(ctx context.Context, cmd *cobra.Command, sessions []strategy.RestoredSession, preferredSessionID string, force bool) error {
363		w := cmd.OutOrStdout()
364		return continueRestoredSessions(ctx, w, sessions, restoredSessionContinueOptions{
365			CanPrompt:          trailResumeCanPromptRestoredSessions(force),
366			PreferredSessionID: preferredSessionID,
367			PromptSession:      promptTrailRestoredSession,
368			Launch:             launchTrailRestoredSession,
369			Display:            displayTrailRestoredSessions,
370			PrintSummary:       printTrailRestoredSessionSummary,
371		})
372	}
373	
374	func printTrailRestoredSessionSummary(w io.Writer, sessions []strategy.RestoredSession) {
375		checkpointID := restoredSessionsCheckpointID(sessions)
376		switch {
377		case checkpointID != "" && len(sessions) > 1:
378			fmt.Fprintf(w, "\n✓ Restored checkpoint %s (%d sessions).\n", checkpointID, len(sessions))
379		case checkpointID != "" && len(sessions) == 1:
380			fmt.Fprintf(w, "✓ Restored checkpoint %s (1 session).\n", checkpointID)
381		case len(sessions) > 1:
382			fmt.Fprintf(w, "\n✓ Restored %d checkpoint sessions.\n", len(sessions))
383		case len(sessions) == 1:
384			fmt.Fprintf(w, "✓ Restored checkpoint session %s.\n", sessions[0].SessionID)
385		}
386		if len(sessions) > 0 && trailRestoredSessionsAreAllReviewOrInvestigation(sessions) {
387			fmt.Fprintln(w, "  Only review/investigation checkpoint sessions were found; these are transcript logs and may not appear as trail UI sessions.")
388		}
389	}
390	
391	func displayTrailRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
392		if len(sessions) == 0 {
393			return nil
394		}
395		choices := buildTrailResumeRestoredSessionChoices(sessions)
396		printTrailRestoredSessionSummary(w, sessions)
397		if len(choices) > 1 {
398			fmt.Fprintln(w, "To continue:")
399		} else {
400			fmt.Fprintln(w, "\nTo continue this checkpoint session:")
401		}
402	
403		isMulti := len(choices) > 1
404		mostRecentSessionID := mostRecentRestoredSessionID(sessions)
405		for _, choice := range choices {
406			sessionAgent, err := strategy.ResolveAgentForRewind(choice.Session.Agent)
407			if err != nil {
408				return fmt.Errorf("failed to resolve agent for session %s: %w", choice.SessionID, err)
409			}
410			printSessionCommand(w, sessionAgent.FormatResumeCommand(choice.SessionID), trailRestoredSessionPrompt(choice.Session), isMulti, choice.SessionID == mostRecentSessionID)
411		}
412		return nil
413	}
414	
415	func mostRecentRestoredSessionID(sessions []strategy.RestoredSession) string {
416		var latestID string
417		var latestTime time.Time
418		for _, session := range sessions {
419			if session.SessionID == "" || session.CreatedAt.IsZero() {
420				continue
421			}
422			if latestID == "" || session.CreatedAt.After(latestTime) {
423				latestID = session.SessionID
424				latestTime = session.CreatedAt
425			}
426		}
427		return latestID
428	}
429	
430	func resolveTrailResumeSessionContexts(ctx context.Context, branch string) ([]trailResumeSessionContext, int, error) {
431		sessions, skipped, err := resolveTrailCheckpointSessions(ctx, branch)
432		if err == nil && len(sessions) > 0 {
433			return sessions, skipped, nil
434		}
435	
436		items, localErr := resolveTrailResumeSessions(ctx, branch)
437		if localErr != nil {
438			if err != nil {
439				return nil, 0, err
440			}
441			return nil, skipped, localErr
442		}
443		localSessions := trailResumeSessionContextsFromLocal(branch, items)
444		if len(localSessions) > 0 {
445			return localSessions, skipped, nil
446		}
447		return sessions, skipped, err
448	}
