725	func trailResumeSelectorForCommands(trail trailResumeTrailContext) string {
726		if trail.Number > 0 {
727			return strconv.Itoa(trail.Number)
728		}
729		if trail.ID != "" {
730			return trail.ID
731		}
732		return trail.Branch
733	}
