735	func shellArg(s string) string {
736		if s == "" {
737			return "''"
738		}
739		for _, r := range s {
740			if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
741				r == '-' || r == '_' || r == '.' || r == '/' || r == ':' {
742				continue
743			}
744			return shellQuote(s)
745		}
746		return s
747	}
