1003	func trailRestoredSessionKindLabel(kind string) string {
1004		switch sessionpkg.Kind(kind) {
1005		case sessionpkg.KindAgentReview:
1006			return "review"
1007		case sessionpkg.KindAgentInvestigate:
1008			return "investigation"
1009		case sessionpkg.KindImported:
1010			return "imported"
1011		default:
1012			return ""
1013		}
1014	}
