1016	func trailRestoredSessionPrompt(session strategy.RestoredSession) string {
1017		if prompt := strings.TrimSpace(session.Prompt); prompt != "" {
1018			return prompt
1019		}
1020		return strings.TrimSpace(session.ReviewPrompt)
