1174		prompt := strings.TrimSpace(session.LastPrompt)
1175		if prompt == "" {
1176			prompt = trailResumeNoPrompt
1177		} else {
1178			prompt = stringutil.TruncateRunes(stringutil.CollapseWhitespace(prompt), 50, "...")
1179		}
1180		agent := session.Agent
1181		if agent == "" {
1182			agent = unknownAgentLabel
1183		}
1184		when := "-"
1185		if !session.LastActive.IsZero() {
