69	// trailResumeReportErrorFrom maps a typed resume error to its JSON object,
70	// or nil when the error is not part of the typed contract.
71	func trailResumeReportErrorFrom(err error) *trailResumeReportError {
72		var clash *ResumeWorktreeClashError
73		if errors.As(err, &clash) {
74			return &trailResumeReportError{
75				Type:         "worktree_clash",
76				Message:      clash.Error(),
77				Branch:       clash.Branch,
78				WorktreePath: clash.WorktreePath,
79			}
80		}
81		var noCheckpoint *ResumeNoCheckpointError
82		if errors.As(err, &noCheckpoint) {
83			return &trailResumeReportError{
84				Type:    "no_checkpoint",
85				Message: noCheckpoint.Error(),
86				Branch:  noCheckpoint.Branch,
87			}
88		}
89		var unavailable *ResumeMetadataUnavailableError
90		if errors.As(err, &unavailable) {
91			return &trailResumeReportError{
92				Type:         "metadata_unavailable",
93				Message:      unavailable.Error(),
