			return fmt.Errorf("encode trail resume action report: %w", err)
		}
		return nil
	}
	fail := func(err error) error {
		reportErr := trailResumeReportErrorFrom(err)
		if reportErr == nil {
			return err
		}
		report := buildTrailResumeActionReport(found, branch, actions, nil, "")
